schema:
syntax = "proto3";
package binanceDepthUpdateRaw.v1;
option optimize_for = SPEED;

enum Exchange {
  EXCHANGE_UNSPECIFIED = 0;
  EXCHANGE_UNRECOGNIZED = 1;
  EXCHANGE_BINANCE = 2;
  EXCHANGE_KUCOIN = 3;
}

message OrderBookEntry {
    double price = 1;
    double quantity = 2;
}

message DepthUpdate {
  string eventType = 1;
  int64 timestampMicro = 2;
  int64 receptionTimeMicro = 3;
  string symbol = 4;
  int64 eventFirstUpdateId = 5;
  int64 eventFinalUpdateId = 6;
  repeated OrderBookEntry bidsToUpdate = 7;
  repeated OrderBookEntry asksToUpdate = 8;
  Exchange Exchange = 9;
  bool isMonitored = 10;
}
